package com.company.platform.order.infrastructure;
import com.company.platform.order.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.Timestamp;import java.util.*;
@Repository public class JdbcOrderRepository implements OrderRepository{private final JdbcTemplate jdbc;private final OrderItemRepository items;public JdbcOrderRepository(JdbcTemplate j,OrderItemRepository i){jdbc=j;items=i;}public Order save(Order o){jdbc.update("INSERT INTO orders(id,tenant_id,order_number,customer_id,store_id,status,currency,subtotal,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=?,subtotal=?,updated_at=?",o.id(),o.tenantId(),o.orderNumber().value(),o.customerId(),o.storeId(),o.status().name(),o.currency().getCurrencyCode(),o.subtotal().amount(),Timestamp.from(o.createdAt()),Timestamp.from(o.updatedAt()),o.status().name(),o.subtotal().amount(),Timestamp.from(o.updatedAt()));for(var i:o.items())jdbc.update("INSERT INTO order_items(id,order_id,tenant_id,sellable_product_id,product_snapshot,quantity,unit_price,subtotal,currency,created_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET quantity=?,subtotal=?",i.id(),o.id(),o.tenantId(),i.sellableProductId(),i.productSnapshot(),i.quantity(),i.unitPrice().amount(),i.subtotal().amount(),i.unitPrice().currency().getCurrencyCode(),Timestamp.from(o.updatedAt()),i.quantity(),i.subtotal().amount());return o;}
 private Order map(java.sql.ResultSet r,int n)throws java.sql.SQLException{UUID id=(UUID)r.getObject("id");UUID t=(UUID)r.getObject("tenant_id");Currency c=Currency.getInstance(r.getString("currency"));return Order.rehydrate(id,t,new OrderNumber(r.getString("order_number")),(UUID)r.getObject("customer_id"),(UUID)r.getObject("store_id"),OrderStatus.valueOf(r.getString("status")),c,new Money(r.getBigDecimal("subtotal"),c),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant(),items.findByTenantIdAndOrderId(t,id));}private List<Order> q(String sql,Object...a){return jdbc.query(sql,this::map,a);}public Optional<Order> findByTenantIdAndId(UUID t,UUID id){return q("SELECT * FROM orders WHERE tenant_id=? AND id=?",t,id).stream().findFirst();}public Optional<Order> findByTenantIdAndOrderNumber(UUID t,String n){return q("SELECT * FROM orders WHERE tenant_id=? AND order_number=?",t,n).stream().findFirst();}public List<Order> findByTenantIdAndCustomerId(UUID t,UUID c){return q("SELECT * FROM orders WHERE tenant_id=? AND customer_id=? ORDER BY created_at DESC",t,c);}public List<Order> findByTenantIdAndStoreId(UUID t,UUID s){return q("SELECT * FROM orders WHERE tenant_id=? AND store_id=? ORDER BY created_at DESC",t,s);}}
